"""Aggregate completed development results; never select models on evaluation slices."""
from common import *
import csv,statistics
def distribution(values):
    return {'median':float(np.median(values)),'p95':float(np.percentile(values,95)),'worst':float(max(values))}
def summarize():
    rows=read(RUN/'evaluation/all-rows.json');fits=read(RUN/'training-summary.json');fmap={f['arm']:f for f in fits};counts=read(RUN/'data/counts.json');summaries=[]
    for method,endpoint,split in sorted({(r['method'],r['checkpoint'],r['split']) for r in rows}):
        rs=[r for r in rows if (r['method'],r['checkpoint'],r['split'])==(method,endpoint,split)];r=rs[0];fit=fmap.get(method);timing=read(RUN/f'baselines/{method}-timing-audit.json') if method in ['nearest','ridge'] else None
        summary={'method':method,'seed':r['seed'],'split':split,'checkpoint_endpoint':endpoint,'checkpoint_update':r['actual_updates'],'actual_fit_updates':fit['actual_updates'] if fit else 0,'selected_update':fit.get('selected_update') if fit else None,'checkpoint_path':fit['selected_checkpoint' if endpoint=='selected' else 'fixed_checkpoint'] if fit else endpoint,'reference_accepted':counts[split]['accepted'],'reference_attempted':counts[split]['attempted'],'evaluated':len(rs),'strict_feasible_n':sum(x['all_tested_constraints_pass'] for x in rs),'strict_feasible_fraction':sum(x['all_tested_constraints_pass'] for x in rs)/len(rs),'trainable_parameters':timing['trainable_parameters_effective'] if timing else r['trainable_parameters'],'training_seconds':timing['standalone_fit_including_input_read_seconds'] if timing else r['training_seconds'],'median_seconds_per_update':r.get('median_seconds_per_update'),'p95_seconds_per_update':r.get('p95_seconds_per_update'),'peak_RSS_bytes':timing['peak_process_tree_RSS_bytes'] if timing else r['peak_RSS_bytes'],'minimum_available_memory_bytes':fit.get('minimum_available_memory_bytes') if fit else (timing['available_memory_bytes'] if timing else None),'stop_reason':r.get('stop_reason'),'status':fit['status'] if fit else 'COMPLETE','rated_branches':0,'thermal_criterion':'not applicable; original RATE_A=0, not evidence of no congestion'}
        for key in ['max_p_residual_mw','max_q_residual_mvar','cost_error_percent','voltage_mae_pu','angle_mae_deg','pg_mae_mw','qg_mae_mvar']:
            for suffix,value in distribution([x[key] for x in rs]).items():summary[key+'_'+suffix]=value
        for key in ['max_voltage_violation_pu','max_generator_component_violation_mw_or_mvar','max_angle_violation_deg','max_branch_violation_mva']:summary[key+'_worst']=max(x[key] for x in rs)
        if method=='ridge':summary['original_three_candidate_tuning_seconds']=read(RUN/'baselines/ridge-selection.json')['fit_seconds_including3_validation_candidates']
        summaries.append(summary)
    save(RUN/'summary.json',summaries)
    keys=list(dict.fromkeys(k for s in summaries for k in s))
    with (RUN/'summary.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=keys);w.writeheader();w.writerows(summaries)
    # Explicit paired changes, same accepted families and selected/fixed endpoints.
    pairs=[];manifest=read(RUN/'data/manifest.json');demand={r['scenario_id']:r for r in manifest['spatial'] if r['accepted']}
    for method,endpoint in sorted({(r['method'],r['checkpoint']) for r in rows}):
        ordinary={r['scenario_id']:r for r in rows if r['method']==method and r['checkpoint']==endpoint and r['split']=='ordinary'}
        spatial=[r for r in rows if r['method']==method and r['checkpoint']==endpoint and r['split']=='spatial']
        for s in spatial:
            o=ordinary[s['pair_id']];dm=demand[s['scenario_id']];pair={'method':method,'endpoint':endpoint,'seed':s['seed'],'ordinary_id':o['scenario_id'],'spatial_id':s['scenario_id'],'region_index':dm['region_index'],'absolute_demand_moved_MW':dm['demand_absolute_moved_MW_MVAr'][0],'absolute_demand_moved_MVAr':dm['demand_absolute_moved_MW_MVAr'][1],'total_P_change_MW':dm['P_Q_total_difference'][0],'total_Q_change_MVAr':dm['P_Q_total_difference'][1],'feasibility_change':int(s['all_tested_constraints_pass'])-int(o['all_tested_constraints_pass'])}
            for k in ['max_p_residual_mw','max_q_residual_mvar','cost_error_percent','voltage_mae_pu','angle_mae_deg','pg_mae_mw','qg_mae_mvar']:pair[k+'_ordinary']=o[k];pair[k+'_spatial']=s[k];pair[k+'_change']=s[k]-o[k]
            pairs.append(pair)
    save(RUN/'paired-summary.json',pairs)
    with (RUN/'paired-summary.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(pairs[0]));w.writeheader();w.writerows(pairs)
    return summaries,pairs,fits
def main():
    s,pairs,fits=summarize();counts=read(RUN/'data/counts.json');audit=read(RUN/'operator-audit.json');smoke=read(RUN/'smoke-summary.json')
    def get(method,split='ordinary',endpoint='selected'):
        return next(r for r in s if r['method']==method and r['split']==split and (r['checkpoint_endpoint']==endpoint or method in ['nearest','ridge','frozen']))
    order=['nearest','ridge','frozen','S','C','E','H','L','R'];lines=['# GSFM-004 Revision2 — completed bounded discovery pilot','',f'Run `{RUN.name}`. Original start21 October2026 10:48:43UTC. CPU FP32 model, original-parameter FP64 C/E physics; seed11 only. No additional topology, MPS, second seed or final-paper test run.','', '## Status and shared data','']
    for experiment in range(5):lines.append(f'- Experiment{experiment}: COMPLETE. '+['Operator/loss/gradient/data-path checks and six disposable20-update smokes passed.','Nearest-example, three-alpha validation-selected ridge and frozen baselines evaluated.','S/C/E completed200 matched updates.','H/L/R completed200 matched updates; heads saved with adapters.','All methods evaluated on10 ordinary,10 paired spatial and10 higher-load development cases.'][experiment])
    lines+=['',f'Accepted/attempted: '+', '.join(k+f" {v['accepted']}/{v['attempted']}" for k,v in counts.items())+'. Two higher-load solver failures remain unknown. Results are conditional on accepted references, and all90 shared cases are development data. Twelve separate smoke cases are excluded. Four regions were defined before model evaluation using farthest-hop centers and nearest ceil(N_positive/4) memberships; exact factor arrays and SVD rank/totals are local.','', '## One comparison table (validation-selected checkpoints)','', '| Method | Selected update | Ordinary median P/Q max,MW/MVAr | Spatial median P/Q max | Higher-load median P/Q max | Ordinary median raw cost error | Feasible ordinary/spatial/high | Trainable parameters | Fit seconds | Peak RSS GiB |','|---|---:|---|---|---|---:|---|---:|---:|---:|']
    for m in order:
        a,b,c=get(m),get(m,'spatial'),get(m,'higher_load');lines.append(f"| {m} | {a['checkpoint_update']} | {a['max_p_residual_mw_median']:.2f}/{a['max_q_residual_mvar_median']:.2f} | {b['max_p_residual_mw_median']:.2f}/{b['max_q_residual_mvar_median']:.2f} | {c['max_p_residual_mw_median']:.2f}/{c['max_q_residual_mvar_median']:.2f} | {a['cost_error_percent_median']:.4f}% | {a['strict_feasible_n']}/{b['strict_feasible_n']}/{c['strict_feasible_n']} of10each | {a['trainable_parameters']:,} | {a['training_seconds']:.2f} | {a['peak_RSS_bytes']/2**30:.3f} |")
    lines+=['','Each P/Q statistic is a median across scenario-wise worst nodal residuals, not across pooled buses. Full median/p95/worst distributions; state/cost errors; limits; selected AND fixed-U endpoints; reference counts; actual updates; measured time/memory and stop reasons are in `summary.csv/json`. All six common endpoints are200; no unequal truncation.','', 'S=pretrained full regression without KCL; C=same with stock floor; E=same with exact KCL; H=four regression heads only; L=rank2 FFN LoRA(alpha2)+the same heads; R=fully random same-architecture regression model. head_feas is frozen and its disconnected forward tail is skipped. Branch objectives have zero eligible branches because RATE_A=0; no synthetic ratings/negative labels. Infeasible raw cost is not an achieved operating cost.','', '## Mechanism evidence and correctness','',f"On the first smoke state, supervised/cost objective={audit['mechanism']['raw_supervised_cost']['total']:.6f}; weighted stock/exact KCL={audit['mechanism']['weighted_stock_kcl']:.6f}/{audit['mechanism']['weighted_exact_kcl']:.6f}. Gradient norms: supervised={audit['mechanism']['gradient_norms']['supervised_cost']:.4f},stock={audit['mechanism']['gradient_norms']['stock_KCL']:.4f},exact={audit['mechanism']['gradient_norms']['exact_KCL']:.4f}. Stock/exact gradient cosine={audit['mechanism']['gradient_cosines']['stock_KCL__exact_KCL']:.6f}; total-C/total-E cosine={audit['mechanism']['gradient_cosines']['total_C__total_E']:.6f}. These are largely aligned signals of different magnitude, not evidence of strongly conflicting gradients. Full raw/weighted components, capacity normalization(326.78435/140.9018pu),80%worst/20%mean aggregation,1%capacity margin, directional probes and active masks are in operator-audit.json.",
'Exact original-precision reference/prediction operator checks agree with the independent evaluator within1.5e-11MW/MVAr, and exact physical metrics are invariant on25/100/400MVA representations. The stock operator biases the exact reference by243.99MW/193.29MVAr. Labels, source-row ordering, system-base units, feasible masks, fresh batches, two-graph forward, feature/prediction independence from labels, pre-sanitizer/module tensors, parameter gradients, zero-LoRA equivalence, frozen parameters and full-state/head reload were checked. No installed model code or forward feature/context/flow equations was changed.','',
'A setup-only error assumed checkpoint metadata always contains arch; the released loader uses default architecture if absent. The same fallback was adopted for R; its original error/source/log are retained in checks/failure-before-random-default-fix. Passed checks and five successful smokes were reused; only the missing R smoke was run afterwards. This is not a numerical training failure.','', '## Learning curves, matched endpoints and demand shift','']
    for fit in fits:lines.append(f"- {fit['arm']}: {fit['actual_updates']} updates; selected{fit['selected_update']}; validation scores "+', '.join(f"{v['update']}:{v['key'][0]:.4f}" for v in fit['validation'])+f"; fit{fit['training_seconds_including_validation_checkpointing']:.2f}s; median/p95 update{fit['median_seconds_per_update']:.3f}/{fit['p95_seconds_per_update']:.3f}s; min available{fit['minimum_available_memory_bytes']/2**30:.2f}GiB; stop reason={fit['stop_reason']}. See training/{fit['arm']}/ for losses, gradients, manifests and resumable checkpoints.")
    lines+=['','Spatial paired changes (mean of paired difference,spatial minus ordinary; all10pairs):','', '| Method | Δ maximum P,MW | Δ maximum Q,MVAr | Δ raw cost error,percentage points | Δ Vm MAE,pu |','|---|---:|---:|---:|---:|']
    for method in order:
        pp=[p for p in pairs if p['method']==method and (p['endpoint']=='selected' or method in ['nearest','ridge','frozen'])]
        lines.append(f"| {method} | {np.mean([x['max_p_residual_mw_change'] for x in pp]):.4f} | {np.mean([x['max_q_residual_mvar_change'] for x in pp]):.4f} | {np.mean([x['cost_error_percent_change'] for x in pp]):.6f} | {np.mean([x['voltage_mae_pu_change'] for x in pp]):.7f} |")
    dm=[p for p in pairs if p['method']=='ridge'];lines+=['',f"Spatial moves: {min(p['absolute_demand_moved_MW'] for p in dm):.2f}–{max(p['absolute_demand_moved_MW'] for p in dm):.2f}MW; maximum total-P drift{max(abs(p['total_P_change_MW']) for p in dm):.3g}MW and total-Q drift{max(abs(p['total_Q_change_MVAr']) for p in dm):.3g}MVAr. Local P/Q ratios and <=10%affected-load change are retained by the recorded SVD projection. Demand movement is not an assumed uniform regional shock. paired-summary.csv/json reports every pair's P/Q, cost, voltage,angle,Pg,Qg and feasibility changes; it is not a bus-level significance test."]
    lines+=['','Matched200-update ordinary median P/Q maxima(MW/MVAr): '+ '; '.join(f"{method} {get(method,endpoint='fixed_U')['max_p_residual_mw_median']:.2f}/{get(method,endpoint='fixed_U')['max_q_residual_mvar_median']:.2f}" for method in ['S','C','E','H','L','R'])+'. At matched200, E has lower P residual but higher Q residual than C; selected-checkpoint improvements are not uniform endpoint dominance.', '', 'Cost/state trade-off: selected E ordinary cost error0.5086% is better than C0.8443%, but worse than S0.2178%. E/C ordinary Vm MAE0.00520/0.00247pu, angle MAE5.264/3.495degrees,Pg MAE12.757/7.444MW,Qg MAE8.935/6.365MVAr: lower E balance residuals come with larger state errors than C. S does not uniformly beat scratch R: at200 updates S has substantially worse P balance but better angle/cost accuracy. H/L use fewer parameters and less fit time, but do not match the stronger physics-penalty arms and have large raw cost errors. No clean pretraining or parameter-efficiency dominance is established.']
    # Findings remain explicitly descriptive; numerical comparisons generated from completed rows.
    E=get('E');C=get('C');S=get('S');ridge=get('ridge');H=get('H');L=get('L');R=get('R');F=get('frozen');fit_seconds=sum(f['training_seconds_including_validation_checkpointing'] for f in fits)
    findings=[f"What ran:90 accepted shared development cases plus12 separate smoke cases; six independent seed11 fits ×200updates; three10-case development slices(30evaluation cases total) and cheap/frozen controls. Main-fit wall time including validation/checkpointing was{fit_seconds/60:.2f}minutes.",
    f"What improved: on ordinary cases, selected E median P/Q max={E['max_p_residual_mw_median']:.2f}/{E['max_q_residual_mvar_median']:.2f}, versus C={C['max_p_residual_mw_median']:.2f}/{C['max_q_residual_mvar_median']:.2f} and S={S['max_p_residual_mw_median']:.2f}/{S['max_q_residual_mvar_median']:.2f}; interpret cost/state/slice changes jointly, with fixed200 endpoints also reported.",
    f"What failed: strict raw feasibility is absent where the table shows0/10; the frozen model and adapted arms must be compared with ridge, whose ordinary median P/Q max is{ridge['max_p_residual_mw_median']:.2f}/{ridge['max_q_residual_mvar_median']:.2f}. S/R ordinary median P/Q max are{S['max_p_residual_mw_median']:.2f}/{S['max_q_residual_mvar_median']:.2f} and{R['max_p_residual_mw_median']:.2f}/{R['max_q_residual_mvar_median']:.2f}; a200-update scratch comparison is early learning only.",
    'Which hypothesis merits a larger study: a narrow numerical-loss trade-off study, with ridge mandatory as a baseline, is better supported than a claim of useful foundation-model adaptation. Selected E lowers balance residuals, but has worse state errors than C and worse raw cost error than S; at matched200 updates its reactive residual is worse than C. Exact-KCL dominance is therefore not established. Do not expand to a large paper matrix before resolving that trade-off.',
    f"Measured compute estimate: this complete six-arm main-fit screen took{fit_seconds:.1f}s. A like-for-like three-seed repeat would be about{3*fit_seconds/60:.1f}main-fit minutes on this host before data/evaluation/report overhead; a1000-update fit is roughly{1000*max(f['p95_seconds_per_update'] for f in fits)/60:.1f}minutes of updates alone at the measured slowest p95, not a guaranteed scaling forecast. No larger study was started."]
    save(RUN/'five-findings.json',findings);(RUN/'five-findings.md').write_text('\n'.join(f'{i+1}. {v}' for i,v in enumerate(findings))+'\n');lines+=['','## Five findings','']+findings
    lines+=['','## Limits, artifacts and reproduction','', 'One seed and10 accepted cases per evaluation slice support descriptive hypothesis screening only. p95/worst estimates are unstable; no across-seed repeatability, significance, universal pretraining advantage, optimal hyperparameter comparison, global optimality, operational feasibility or conference acceptance claim is justified. Ridge had three validation-only alpha candidates; common neural lr is a controlled screen, not each method’s optimum.','',
'Training uses AdamW1e-4,weight decay1e-4,clip1,batch1,Torch4/BLAS1/workers0. Common U=200 was fixed from slowest smoke p95 before viewing main outcomes. Per-fit25minute and update caps,4h40compute cutoff,5hour total cutoff and RSS32GiB/available12GiB bounds were enforced. Peak RSS is sampled process-tree residency every0.2s; NN/ridge timing/RSS were supplemented by a standalone NumPy-only reconstruction at the same fixed parameters, with no additional alpha search; contexts differ and no matched memory-saving claim is made. Original ridge tuning time is separately retained.','',
'Raw matrices, factor arrays, solver results/failures, model/optimizer/RNG checkpoints and per-scenario predictions remain local under this run directory with hashes. Compact summaries/scripts are committed and pushed; do not assume ignored data or weights exist on GitHub. Rebuild labels from pinned MATPOWER source and saved manifest seeds/factors, then run the same scripts. Original base evidence remains in results/inference and results/diagnosis.','',
'Explicit new replay (never reset the current run clock):','', '```sh','export GSFM004_RUN_ID=<new-unique-run-id>','export GSFM004_START_UTC=<actual-new-start-ISO8601-with-timezone>',str(MODEL/'model/.venv/bin/python')+' -B experiments/gsfm004/data.py',str(MODEL/'model/.venv/bin/python')+' -B experiments/gsfm004/audit.py',str(MODEL/'model/.venv/bin/python')+' -B experiments/gsfm004/fit.py','```','',
'Create the new output directory first with a RUNNING status; original source/checkpoint and working Julia project are prerequisites. Complete commands, environment, all hashes, ignored-artifact inventory and local paths are in provenance.json and artifact-manifest.json. Checkpoints include model,optimizer,RNG,update/order and base-checkpoint identity; no automatic resume beyond the original cutoff.']
    text='\n'.join(lines)+'\n'
    for a,b in {'Original start21 October2026':'Original start 21 October 2026','10:48:43UTC':'10:48:43 UTC','Experiment0:':'Experiment 0:','Experiment1:':'Experiment 1:','Experiment2:':'Experiment 2:','Experiment3:':'Experiment 3:','Experiment4:':'Experiment 4:','completed200':'completed 200','disposable20-update':'disposable 20-update','on10 ordinary,10 paired spatial and10':'on 10 ordinary, 10 paired spatial and 10','all90':'all 90','all10pairs':'all 10 pairs','What ran:90':'What ran: 90','plus12':'plus 12','seed11':'seed 11','×200updates':'× 200 updates','three10-case':'three 10-case','(30evaluation':'(30 evaluation'}.items():text=text.replace(a,b)
    (RUN/'README.md').write_text(text);save(RUN/'data-summary.json',{'counts':counts,'regions':read(RUN/'data/regions.json'),'max_abs_P_drift_MW':max(abs(p['total_P_change_MW']) for p in dm),'max_abs_Q_drift_MVAr':max(abs(p['total_Q_change_MVAr']) for p in dm),'data_design':'all development,not final test'})
    log('REPORT_AGGREGATED',rows=len(s),paired_rows=len(pairs))
if __name__=='__main__':main()
